    if line.startswith('>'):
        if current_name:
            sequences[current_name] = current_seq
        current_name = line[1:]
        current_seq = ''
    else:
        current_seq += line

if current_name:
    sequences[current_name] = current_seq

for name, seq in sequences.items():
    print(f"{name}: {len(seq)} bp")

# Find differences
input_seq = sequences['input']
output_seq = sequences['output']

if len(input_seq) == len(output_seq):
    diffs = []
    for i in range(len(input_seq)):
        if input_seq[i] != output_seq[i]:
            diffs.append((i, input_seq[i], output_seq[i]))
    print(f"\nNumber of differences: {len(diffs)}")
