        for pos, inp, out in diffs:
            print(f"Position {pos}: {inp} -> {out}")
    else:
        print("First 10 differences:")
        for pos, inp, out in diffs[:10]:
            print(f"Position {pos}: {inp} -> {out}")
else:
    print(f"\nSequence lengths differ: input {len(input_seq)} vs output {len(output_seq)}")
